using System;using System.Collections.Generic;using System.Linq;using System.IO;using System.Text;using System.Diagnostics;using System.Threading;using Azurite.Restricted;
internal static class FullRestrictedNativeTests {
 static int count;static void Check(bool value,string why){count++;if(!value)throw new Exception(why);}
 static void Refuse(Action action,string why){bool failed=false;try{action();}catch{failed=true;}Check(failed,why);}
 static int Main(){try{return Tests();}catch(Exception e){Console.WriteLine("FAIL: "+e.Message);return 1;}} static int Tests(){
  string run=new string('a',32),dir=FullRestrictedContract.Lab+"\\runs\\restricted-"+run;
  FullRestrictedContract.ValidateRequest(run,dir,"capabilities",FullRestrictedContract.Executable,"-batchmode -nographics -disableaudio -logFile "+dir+"\\output\\unity.log",dir+"\\request",null);
  Refuse(()=>FullRestrictedContract.ValidateRequest(run,dir,"schema",FullRestrictedContract.Executable,"x",dir+"\\request",null),"schema denied");
  Refuse(()=>FullRestrictedContract.ValidateRequest(run,dir,"capabilities","C:\\fake.exe","x",dir+"\\request",null),"arbitrary target denied");
  Refuse(()=>FullRestrictedContract.ValidateRequest(run,dir,"capabilities",FullRestrictedContract.Executable,"x",dir+"\\request","C:\\override.dll"),"game assembly override denied");
  foreach(uint bad in new uint[]{0,2,UInt32.MaxValue}){var fake=new Fake(bad);var r=FullRestrictedCoordinator.Run(fake);Check(!r.ResumeVerified&&r.ResumeCalls==1&&fake.Closed&&fake.Terminated,"single resume/cleanup on invalid previous count");}
  var okay=new Fake(1);var good=FullRestrictedCoordinator.Run(okay);Check(good.ResumeVerified&&good.CleanupVerified&&okay.Order.IndexOf("lease")<okay.Order.IndexOf("resume"),"lease/token/job precede one resume");
  foreach(string stage in new[]{"token","lease","create","actual-token","job","streams","monitor","drain","close"}){var fake=new Fake(1){Fail=stage};var r=FullRestrictedCoordinator.Run(fake);Check((r.Error!=null||r.CleanupError!=null)&&fake.Closed,"stage error retained and cleanup attempted: "+stage);Check(!fake.Created||fake.Terminated,"owned process cleanup: "+stage);if(new[]{"token","lease","create","actual-token","job","streams"}.Contains(stage))Check(r.ResumeCalls==0,"no early resume "+stage);}
  Refuse(()=>FullRestrictedContract.ValidateMembers(10,20,new[]{10,20,30}),"unexpected helper rejected");FullRestrictedContract.ValidateMembers(10,20,new[]{20,10});
  Refuse(()=>FullRestrictedContract.ValidateHandleList(new long[]{4,5,6},new long[]{4,5,6,7}),"extra inherited handle rejected");FullRestrictedContract.ValidateHandleList(new long[]{4,5,6},new long[]{4,5,6});
  Refuse(()=>FullRestrictedContract.ValidateHandleList(new long[]{4,4,6},new long[]{4,4,6}),"duplicate endpoint rejected");
  var handles=new[]{"stdin-child-reader","stdout-child-writer","stderr-child-writer","stdin-parent-writer","stdout-parent-reader","stderr-parent-reader"}.Select((role,i)=>new FullHandleEvidence{Role=role,Handle=10+i,Flags=i<3?1u:0u,FileType=3}).ToArray();
  FullRestrictedContract.ValidateHandleEvidence(handles,new long[]{10,11,12},new long[]{20,21,22,23});Check(true,"queried six-handle evidence accepted");
  handles[4].Flags=1;Refuse(()=>FullRestrictedContract.ValidateHandleEvidence(handles,new long[]{10,11,12},new long[]{20,21,22,23}),"inheritable parent reader denied");handles[4].Flags=0;
  handles[1].Flags=0;Refuse(()=>FullRestrictedContract.ValidateHandleEvidence(handles,new long[]{10,11,12},new long[]{20,21,22,23}),"noninheritable child denied");handles[1].Flags=1;
  handles[2].FileType=1;Refuse(()=>FullRestrictedContract.ValidateHandleEvidence(handles,new long[]{10,11,12},new long[]{20,21,22,23}),"nonpipe child denied");handles[2].FileType=3;
  Refuse(()=>FullRestrictedContract.ValidateHandleEvidence(handles,new long[]{10,11,12},new long[]{20,11,22,23}),"sensitive handle included denied");
  Refuse(()=>FullRestrictedContract.ValidateHandleEvidence(handles,new long[]{10,12,11},new long[]{20,21,22,23}),"reordered handle list denied");
  Check(FullProtocol.ReadLine(new StringReader("ACK\r\n"))=="ACK","bounded protocol reader");
  Refuse(()=>FullProtocol.ReadLine(new StringReader("")),"protocol EOF denied");Refuse(()=>FullProtocol.ReadLine(new StringReader(new string('a',513)+"\n")),"protocol flood denied");
  Check(FullProtocol.JobHandle("AZURITE_JOB_V1 "+run+" 2A",run)==42,"correlated Job protocol parsed");Refuse(()=>FullProtocol.JobHandle("AZURITE_JOB_V1 "+new string('b',32)+" 2A",run),"wrong Job run denied");Refuse(()=>FullProtocol.JobHandle("AZURITE_JOB_V1 "+run+" FFFFFFFFFFFFFFFF",run),"pseudo Job handle denied");
  string owner="S-1-5-21-1-2-3-1001",line="AZURITE_DESKTOP_V1 "+run+" 2A AzuriteFullCli_"+run+" "+owner;
  Check(FullProtocol.DesktopHandle(line,run,owner)==42,"correlated desktop protocol parsed");Refuse(()=>FullProtocol.DesktopHandle(line,run,"S-1-5-21-4-5-6-1001"),"wrong desktop owner denied");Refuse(()=>FullProtocol.DesktopHandle(line.Replace("AzuriteFullCli_","Other_"),run,owner),"wrong desktop name denied");
  Refuse(()=>WindowProbe.RequireWindowOwner(0,0,5),"window owner failure is not absence");Refuse(()=>WindowProbe.RequireWindowOwner(1,0,0),"zero PID is not absence");Check(WindowProbe.RequireWindowOwner(2,42,0)==42,"window PID preserved");
  string hash=new string('b',64);var start=new ProcessStartInfo{FileName=Path.Combine(Environment.SystemDirectory,@"WindowsPowerShell\v1.0\powershell.exe"),Arguments="-NoProfile -NonInteractive -ExecutionPolicy Bypass -File "+dir+@"\tooling\RestrictedCliBootstrap.ps1 -ControlPath "+dir+@"\tooling\control.json -ReviewedControlSha256 "+hash,WorkingDirectory=dir,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};
  FullRestrictedContract.ValidateBootstrap(start,run,hash);Check(true,"fixed bootstrap accepted as pure data");start.Arguments+=" -Command calc";Refuse(()=>FullRestrictedContract.ValidateBootstrap(start,run,hash),"extra bootstrap argument denied");start.Arguments=start.Arguments.Substring(0,start.Arguments.Length-14);start.FileName=@"C:\elsewhere\powershell.exe";Refuse(()=>FullRestrictedContract.ValidateBootstrap(start,run,hash),"arbitrary bootstrap host denied");
  var utf8=new BoundedPipeCapture(16);utf8.Drain(new PipeFake(new[]{new byte[]{0xE2},new byte[]{0x82,0xAC}},109));Check(utf8.Complete&&utf8.Finished&&utf8.Error==null&&utf8.Snapshot()=="€","split UTF8 survives until EOF");
  var truncated=new BoundedPipeCapture(16);truncated.Drain(new PipeFake(new[]{new byte[]{0xE2,0x82}},109));Check(!truncated.Complete&&truncated.Finished&&truncated.Error!=null,"truncated UTF8 flush is failure");
  var invalid=new BoundedPipeCapture(16);invalid.Drain(new PipeFake(new[]{new byte[]{0xFF}},109));Check(!invalid.Complete&&invalid.Error!=null,"invalid UTF8 is failure");
  var eof=new BoundedPipeCapture(16);eof.Drain(new PipeFake(new byte[0][],109));Check(eof.Complete&&eof.Snapshot()=="","clean EOF without output accepted");
  var denied=new BoundedPipeCapture(16);denied.Drain(new PipeFake(new[]{Encoding.UTF8.GetBytes("prefix")},5));Check(!denied.Complete&&denied.Finished&&denied.Error!=null&&denied.Snapshot()=="prefix","native read error retained with partial data");
  var zero=new BoundedPipeCapture(16);zero.Drain(new PipeFake(new[]{new byte[0]},109));Check(!zero.Complete&&zero.Error!=null,"unexpected zero successful read denied");
  var flood=new BoundedPipeCapture(8);flood.Drain(new PipeFake(new[]{Encoding.UTF8.GetBytes(new string('x',4096)),Encoding.UTF8.GetBytes("tail")},109));Check(flood.Complete&&flood.Overflow&&flood.Snapshot().Length==8,"flood retained only to bound but drained to EOF");
  var blocked=new WaitingPipe();var slow=new BoundedPipeCapture(8);slow.Start(blocked);try{Check(blocked.Entered.WaitOne(1000),"fake blocking reader reached same capture worker");var watch=Stopwatch.StartNew();Check(!slow.Finish(20)&&watch.ElapsedMilliseconds<1000&&!slow.CanClose&&!slow.Complete,"lingering writer returns bounded failure and forbids reader close");Refuse(()=>slow.Start(blocked),"pipe worker cannot restart");}finally{blocked.Release.Set();}Check(slow.Finish(1000)&&slow.CanClose&&slow.Complete,"worker release establishes joined EOF");
  Check(!FullRestrictedContract.CanReleaseDesktop(true,false)&&!FullRestrictedContract.CanReleaseDesktop(false,true)&&FullRestrictedContract.CanReleaseDesktop(true,true),"desktop close requires direct exit and exact drain");
  var late=new DrainFake{Counts=new[]{1,1,0},LateWindow=true};var lateResult=FullOuterDrain.Run(late,100);Check(lateResult.DirectExited&&lateResult.JobDrained&&lateResult.WindowViolation&&lateResult.DesktopClosed&&late.Probes==3&&late.ClosedAt==2,"outer still probes after bootstrap exit and before final close");
  foreach(string fail in new[]{"query","monitor","capture","close"}){var fake=new DrainFake{Counts=new[]{0},Fail=fail};var result=FullOuterDrain.Run(fake,100);Check(!result.Verified&&result.Error!=null,"outer failure never passes "+fail);if(fail=="query"||fail=="close")Check(fake.Retained,"uncertain/failed lease retained "+fail);}
  var writer=new DrainFake{Counts=new[]{0},Streams=false};var writerResult=FullOuterDrain.Run(writer,100);Check(!writerResult.Verified&&!writerResult.StreamsComplete&&writerResult.Error!=null,"lingering writer cannot yield success from empty snapshot");
  var stuck=new DrainFake{Counts=new[]{1,1,1},Streams=true};var stuckResult=FullOuterDrain.Run(stuck,20);Check(!stuckResult.JobDrained&&stuckResult.DesktopRetained&&!stuck.Closed&&stuck.Ticks==20,"bounded undrained Job retains desktop");
  var clean=new DrainFake{Counts=new[]{1,0}};Check(FullOuterDrain.Run(clean,100).Verified&&clean.Probes==2,"verified outer drain and close");
  var token=new Dictionary<string,object>{{"user_sid","S-1-5-21-1-2-3-1001"},{"logon_sid","S-1-5-5-1-2"},{"session_id",1},{"token_type",1},{"is_restricted",false},{"elevated",false},{"is_app_container",false},{"app_container_raw",0},{"users_group_count",1},{"users_group_attributes",7},{"users_enabled",true},{"integrity_sid","S-1-16-8192"},{"integrity_rid",8192},{"integrity_attributes",96},{"mandatory_policy",3}};FullRestrictedToken.ValidateOriginal(token);var child=new Dictionary<string,object>(token);child["is_restricted"]=true;child["restricting_sids"]=new[]{"S-1-5-5-1-2","S-1-1-0","S-1-5-32-545"};child["privileges"]=new object[]{new Dictionary<string,object>{{"name","SeChangeNotifyPrivilege"},{"attributes",3}}};FullRestrictedToken.ValidateChild(child,token);
  foreach(string field in new[]{"user_sid","logon_sid","session_id","integrity_rid","mandatory_policy","users_enabled","restricting_sids"}){var bad=new Dictionary<string,object>(child);bad.Remove(field);Refuse(()=>FullRestrictedToken.ValidateChild(bad,token),"missing actual token field "+field);}
  Console.WriteLine("{\"schema\":1,\"mode\":\"source-linked native coordinator fakes only\",\"passed\":true,\"checks\":"+count+"}");return 0;
 }
 sealed class PipeFake:IFullPipeRead {readonly byte[][] pieces;readonly int finalError;int index;internal PipeFake(byte[][] data,int error){pieces=data;finalError=error;}public int Read(byte[] buffer,out int count){if(index>=pieces.Length){count=0;return finalError;}byte[] next=pieces[index++];count=next.Length;Array.Copy(next,buffer,count);return 0;}}
 sealed class WaitingPipe:IFullPipeRead {internal readonly ManualResetEvent Entered=new ManualResetEvent(false),Release=new ManualResetEvent(false);public int Read(byte[] buffer,out int count){Entered.Set();if(!Release.WaitOne(2000))throw new TimeoutException("Test cleanup failed to release fake reader");count=0;return 109;}}
 sealed class DrainFake:IFullOuterDrain {
  public int[] Counts;public bool LateWindow,Streams=true,Closed,Retained;public string Fail;public int Probes,ClosedAt=-1;public long Ticks;int index;
  public long Milliseconds{get{return Ticks;}}public bool DirectExited(){return true;}public int ActiveProcesses(){if(Fail=="query")throw new Exception("job query denied");return Counts[Math.Min(index,Counts.Length-1)];}
  public bool WindowViolation(){Probes++;if(Fail=="monitor")throw new Exception("desktop enumeration failed");return LateWindow&&index==1;}
  public bool FinishStreams(int remaining){if(Fail=="capture")throw new Exception("pipe read error");return Streams;}public void CloseDesktop(){if(Fail=="close")throw new Exception("CloseDesktop failed");if(Counts[Math.Min(index,Counts.Length-1)]!=0)throw new Exception("premature close");Closed=true;ClosedAt=index;}public void RetainDesktop(){Retained=true;}public void Pause(int ms){Ticks+=ms;index++;}
 }
 sealed class Fake:IFullRestrictedOperations {
  public string Fail;public bool Created,Terminated,Closed;public List<string> Order=new List<string>();readonly uint resume;
  public Fake(uint value){resume=value;}void Step(string s){Order.Add(s);if(Fail==s)throw new Exception("fake "+s);}
  public void ReadOriginalAndDerive(){Step("token");}public void AcquireDesktopLease(){Step("lease");}public void CreateSuspended(){Step("create");Created=true;}public void ValidateActualToken(){Step("actual-token");}public void ValidateExactJob(){Step("job");}public void PrepareStreams(){Step("streams");}public uint Resume(){Step("resume");return resume;}public void Monitor(){Step("monitor");}public bool Cleanup(){if(Created)Terminated=true;Step("drain");return true;}public void Close(){Closed=true;Step("close");}
 }
}
